import React, { Component } from 'react';
import axios from 'axios';
import { Button } from 'react-bootstrap';

// Daily Threat Reports - download button for the Cyber Watch page.
// The PDFs themselves are generated by cyber_watch/reports.py:
// daily at 08:00 by the scheduler, or on demand by the management
// command, or by the Generate button below. This panel only lists
// the PDFs already in <BASE_DIR>/reports and downloads them.
// Download uses axios with the Knox token (localStorage 'token'),
// because a plain <a href> would not send the Token header and
// the API would reject it as unauthenticated.
const authHeaders = () => {
    const token = localStorage.getItem('token');
    return token ? { Authorization: `Token ${token}` } : {};
};

const formatSize = (bytes) => {
    if (!bytes && bytes !== 0) return '-';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
};

class DailyReports extends Component {
    constructor(props) {
        super(props);
        this.state = {
            reports: [],
            loading: true,
            generating: false,
            downloading: null,
            error: '',
            message: '',
        };
    }

    componentDidMount() {
        this.fetchReports();
    }

    fetchReports = () => {
        this.setState({ loading: true, error: '' });
        axios.get('/api/cyber_watch/daily-reports/', { headers: authHeaders() })
            .then(res => this.setState({ reports: res.data || [], loading: false }))
            .catch(err => this.setState({
                loading: false,
                error: err.response?.data?.detail || 'Could not load daily reports. Please refresh the page and try again.',
            }));
    };

    handleGenerate = () => {
        this.setState({ generating: true, error: '', message: '' });
        axios.post('/api/cyber_watch/daily-reports/generate/', {}, { headers: authHeaders() })
            .then(res => {
                const counts = res.data.counts || {};
                this.setState({
                    generating: false,
                    message: `Report generated: ${res.data.pdf_filename} - ${counts.cves || 0} new CVEs, ${counts.victims || 0} new victims, ${counts.hits || 0} hits. Email: ${res.data.email_status || ''}`,
                });
                this.fetchReports();
            })
            .catch(err => this.setState({
                generating: false,
                error: err.response?.data?.detail || 'Could not generate daily report. Please try again.',
            }));
    };

    handleDownload = (report) => {
        this.setState({ downloading: report.filename, error: '' });
        axios.get(report.download_url, { headers: authHeaders(), responseType: 'blob' })
            .then(res => {
                const url = window.URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' }));
                const link = document.createElement('a');
                link.href = url;
                link.download = report.filename;
                document.body.appendChild(link);
                link.click();
                link.remove();
                window.URL.revokeObjectURL(url);
                this.setState({ downloading: null });
            })
            .catch(() => this.setState({
                downloading: null,
                error: 'Could not download that report. Please try again.',
            }));
    };

    render() {
        const { reports, loading, generating, downloading, error, message } = this.state;
        const latest = reports.length > 0 ? reports[0] : null;

        return (
            <div>
                <div className="d-flex flex-wrap gap-2 align-items-center mb-2">
                    <Button
                        variant="primary"
                        size="sm"
                        onClick={() => latest && this.handleDownload(latest)}
                        disabled={!latest || !!downloading}
                    >
                        {downloading ? 'Downloading...' : 'Download latest report'}
                    </Button>
                    <Button
                        variant="outline-primary"
                        size="sm"
                        onClick={this.handleGenerate}
                        disabled={generating}
                    >
                        {generating ? 'Generating...' : 'Generate daily report now'}
                    </Button>
                    <Button variant="outline-secondary" size="sm" onClick={this.fetchReports} disabled={loading}>
                        Refresh
                    </Button>
                    <span className="text-muted small">
                        PDFs are generated daily at 08:00, or on demand with the button above.
                    </span>
                </div>

                {error && <div className="alert alert-danger py-2">{error}</div>}
                {message && <div className="alert alert-success py-2">{message}</div>}

                {loading ? (
                    <p className="text-muted small">Loading reports...</p>
                ) : reports.length === 0 ? (
                    <p className="text-muted small">
                        No daily reports yet. Click &quot;Generate daily report now&quot; to create the first one.
                    </p>
                ) : (
                    <div style={{ maxHeight: 260, overflowY: 'auto' }}>
                        <table className="table table-sm table-striped mb-0">
                            <thead>
                                <tr>
                                    <th>Report</th>
                                    <th>Generated</th>
                                    <th>Size</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                {reports.map(report => (
                                    <tr key={report.filename}>
                                        <td style={{ wordBreak: 'break-all' }}>{report.filename}</td>
                                        <td>{report.created_at ? new Date(report.created_at).toLocaleString() : '-'}</td>
                                        <td>{formatSize(report.size)}</td>
                                        <td>
                                            <Button
                                                variant="outline-primary"
                                                size="sm"
                                                onClick={() => this.handleDownload(report)}
                                                disabled={downloading === report.filename}
                                            >
                                                {downloading === report.filename ? 'Downloading...' : 'Download'}
                                            </Button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        );
    }
}

export default DailyReports;
